61	 * — the reciprocal set a search engine needs to read four URLs as one page in
62	 * four languages rather than four pages competing. `x-default` is the default
63	 * language's URL: what to serve a reader whose own language is not among them.
64	 */
65	function localizationBlock(code, indent) {
66	  const lines = [
67	    `<link rel="canonical" href="${ORIGIN}${localeHref(code, FESTIVAL.pageRoot)}" />`,
68	    ...LOCALES.map(
69	      (l) => `<link rel="alternate" hreflang="${l.code}" href="${ORIGIN}${localeHref(l.code, FESTIVAL.pageRoot)}" />`
70	    ),
71	    `<link rel="alternate" hreflang="x-default" href="${ORIGIN}${localeHref(DEFAULT_LOCALE, FESTIVAL.pageRoot)}" />`,
72	  ];
73	  return lines.map((l) => indent + l).join("\n");
74	}
