76	function replaceManagedBlock(html, code) {
77	  const start = html.indexOf(BEGIN);
78	  const end = html.indexOf(END);
79	  if (start < 0 || end < 0) throw new Error(`${SOURCE}: the localization: block is missing`);
80	  const lineStart = html.lastIndexOf("\n", start) + 1;
