1	#!/usr/bin/env node
2	//
3	// Derives one served page per language from the festival planner's own
4	// index.html, so a language is an address rather than a runtime decision.
5	//
6	// What that buys, and why the strings are baked in rather than left to the
7	// page's own applyTranslations(): a browser decides whether to offer a
8	// translation from the document it received. A page that arrives in English
9	// and becomes Hebrew a moment later is offered the wrong translation, and a
10	// crawler that is served a different language per request has one URL to index
11	// for four languages. Both are answered by shipping each language as its own
12	// document, already in that language.
13	//
14	//   node scripts/localize-pages.mjs            write the pages
15	//   node scripts/localize-pages.mjs --check    re-derive and compare, exit 1 on drift
16	//
17	// The source page IS the default language's page: this writes each other
18	// language beside it, and maintains the `localization:` block — canonical and
19	// hreflang — in all of them, that one block being the only part of the default
20	// language's own page it owns.
21	
22	import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
23	import { dirname, join } from "node:path";
24	import { fileURLToPath, pathToFileURL } from "node:url";
25	
26	const REPO = join(dirname(fileURLToPath(import.meta.url)), "..");
27	const PAGE_DIR = join(REPO, "site", "planJerusalem");
28	const SOURCE = join(PAGE_DIR, "index.html");
29	
30	const { DEFAULT_LOCALE, LOCALES, STRINGS } = await import(
31	  join(PAGE_DIR, "i18n", "translations.js")
32	);
33	const { localeHref } = await import(join(PAGE_DIR, "i18n", "i18n.js"));
34	const { FESTIVAL } = await import(join(PAGE_DIR, "festival.js"));
35	
36	// The one hostname the site answers on, and so the one a canonical and an
37	// hreflang may name: an alternate that named a host the site does not serve
38	// would point a crawler at nothing. The wrangler config routes the apex here
39	// too, which is exactly what a canonical exists to consolidate.
40	export const ORIGIN = "https://www.edfringenow.com";
41	
42	/**
43	 * Every language this page is served in: what it is called, which way it runs,
44	 * the URL it answers on and the file that answers. One list, so the generator
45	 * and the requirements that check its output never disagree about where a
46	 * language lives.
47	 */
48	export const PAGES = LOCALES.map((locale) => ({
49	  ...locale,
50	  url: localeHref(locale.code, FESTIVAL.pageRoot),
51	  file:
52	    locale.code === DEFAULT_LOCALE ? SOURCE : join(PAGE_DIR, locale.code, "index.html"),
53	}));
54	
55	const BEGIN = "<!-- localization:begin";
56	const END = "<!-- localization:end -->";
57	
58	const escapeHtml = (s) =>
59	  String(s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
60	
61	/** One language's string for a key, in the language it is being written for. */
62	function t(key, code) {
63	  const entry = STRINGS[key];
64	  if (!entry) throw new Error(`no such translation key: ${key}`);
65	  const value = entry[code];
66	  if (typeof value !== "string") throw new Error(`${key}: no ${code} translation`);
67	  return value;
68	}
69	
70	/**
71	 * The canonical and hreflang block every language carries.
72	 *
73	 * Each page names itself canonical and lists every language including its own
74	 * — the reciprocal set a search engine needs to read four URLs as one page in
75	 * four languages rather than four pages competing. `x-default` is the default
76	 * language's URL: what to serve a reader whose own language is not among them.
77	 */
78	function localizationBlock(code, indent) {
79	  const lines = [
80	    `<link rel="canonical" href="${ORIGIN}${localeHref(code, FESTIVAL.pageRoot)}" />`,
81	    ...LOCALES.map(
82	      (l) => `<link rel="alternate" hreflang="${l.code}" href="${ORIGIN}${localeHref(l.code, FESTIVAL.pageRoot)}" />`
83	    ),
84	    `<link rel="alternate" hreflang="x-default" href="${ORIGIN}${localeHref(DEFAULT_LOCALE, FESTIVAL.pageRoot)}" />`,
85	  ];
86	  return lines.map((l) => indent + l).join("\n");
87	}
88	
89	function replaceManagedBlock(html, code) {
90	  const start = html.indexOf(BEGIN);
91	  const end = html.indexOf(END);
92	  if (start < 0 || end < 0) throw new Error(`${SOURCE}: the localization: block is missing`);
