import pathlib
p = pathlib.Path("product/requirements/shared/case-helpers.js")
s = p.read_text()
old = """async function settle(page) {
  await page.evaluate(() => document.fonts.ready);
  await page.waitForTimeout(250);
}"""
new = """/* Settled means the page has stopped changing, not that a fixed pause has
 * elapsed: a pause long enough on an idle machine captures mid-render on a busy
 * one, and which case pays for it is whichever happened to be rendering — so
 * the flake lands on a different golden each run and reads as unrelated.
 *
 * Fonts first, then the document's own shape held still across consecutive
 * animation frames. The signature is what a capture can see move: the page's
 * dimensions, how many elements are in it, and how much text they hold, which
 * together cover the late arrivals here — a panel filling in, a popup opening,
 * a count being written. Animations are frozen by the harness, so a page that
 * never stabilises is a broken one and the timeout is right to fire. */
const SETTLE_FRAMES = 3;

async function settle(page) {
  await page.evaluate(() => document.fonts.ready);
  await page.evaluate(() => {
    delete window.__settleWatch;
  });
  await page.waitForFunction(
    (frames) => {
      const signature = [
        document.documentElement.scrollHeight,
        document.documentElement.scrollWidth,
        document.querySelectorAll("*").length,
        document.body.textContent.length,
      ].join(":");
      const watch = (window.__settleWatch ||= { signature: null, held: 0 });
      if (watch.signature === signature) watch.held += 1;
      else {
        watch.signature = signature;
        watch.held = 0;
      }
      return watch.held >= frames;
    },
    SETTLE_FRAMES,
    { polling: "raf", timeout: 20000 }
  );
}"""
